mapper.select:
SELECT * FROM em_monitoring_event

    AND project_id = #{projectId}

ORDER BY detected_at DESC, id DESC
LIMIT #{limit}

SELECT e.id, e.event_code AS eventCode, e.project_id AS projectId, e.station_id AS stationId, e.instrument_id AS instrumentId, e.metric_code AS metricCode, e.event_type AS eventType, e.event_level AS eventLevel, e.event_status AS eventStatus, e.detected_at AS detectedAt, e.trigger_value AS triggerValue, e.threshold_value AS thresholdValue, e.unit, e.trigger_reason AS triggerReason, s.station_code AS stationCode, COALESCE(NULLIF(s.station_name, ''), s.station_code) AS stationName, s.station_type AS stationType, i.instrument_code AS instrumentCode, COALESCE(NULLIF(i.instrument_name, ''), i.instrument_code) AS instrumentName, i.instrument_type AS instrumentType, i.status AS instrumentStatus FROM em_monitoring_event e LEFT JOIN em_station s ON s.id = e.station_id LEFT JOIN em_instrument i ON i.id = e.instrument_id
AND e.project_id = #{projectId}
ORDER BY e.detected_at DESC, e.id DESC LIMIT #{limit}

SELECT * FROM em_monitoring_event
WHERE project_id = #{projectId} AND event_code = #{eventCode}
LIMIT 1
